def normalized(node):
    node = copy.deepcopy(node)
    for part in ast.walk(node):
        if isinstance(part, ast.Constant) and isinstance(part.value, str):
            part.value = "<string>"
    return ast.dump(node, include_attributes=False)


def digest(value):
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def algorithm_fingerprint(name, tree):
    # The English UI needs equivalent English placeholder recognition. Retain
    # the original five-token check and normalize only its two added synonyms.
    if name == "task_preflight.py":
        tree = copy.deepcopy(tree)
        original = {"请填写", "自动填写", "TODO", "<", ">"}
        translated = {"Enter a value", "Auto-fill"}
        for node in ast.walk(tree):
            if isinstance(node, ast.Tuple) and all(isinstance(value, ast.Constant) for value in node.elts):
                values = [value.value for value in node.elts]
                if all(isinstance(value, str) for value in values) and set(values) == original | translated:
                    node.elts = [value for value in node.elts if value.value not in translated]
    return digest(normalized(tree))


def declarations(tree):
    result = []

    def walk(node, prefix=""):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
                name = prefix + child.name
                result.append(name)
                walk(child, name + ".")
            else:
                walk(child, prefix)

    walk(tree)
    return sorted(result)


def controls(tree):
    commands, events, widgets = Counter(), Counter(), Counter()
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
            if node.func.value.id in ("tk", "ttk"):
                widgets[ast.unparse(node.func)] += 1
        for keyword in node.keywords:
            if keyword.arg in ("command", "validatecommand", "postcommand"):
                commands[digest(normalized(keyword.value))] += 1
        if isinstance(node.func, ast.Attribute) and node.func.attr in ("bind", "bind_all", "dnd_bind"):
            events[ast.dump(node.args[0], include_attributes=False) if node.args else ""] += 1
    return {"commands": dict(commands), "events": dict(events), "widgets": dict(widgets)}


def assigned(tree, name):
    for node in tree.body:
        if isinstance(node, ast.Assign) and any(isinstance(target, ast.Name) and target.id == name for target in node.targets):
            return ast.literal_eval(node.value)
    raise ValueError(f"Missing declaration: {name}")


def snapshot(root):
    root = Path(root)
    files = {path.relative_to(root).as_posix(): path
             for path in (root / "app").rglob("*")
             if path.is_file() and "__pycache__" not in path.parts and path.suffix != ".pyc"}
    modules, trees = {}, {}
    for name, path in files.items():
        if path.suffix != ".py":
            continue
        tree = ast.parse(path.read_text(encoding="utf-8-sig"))
        trees[name] = tree
        helper_names = {helper for item in REVIEWED_LAYOUT_ADAPTATIONS.values() for helper in item["helpers"]}
        helper_calls = Counter(node.func.id for node in ast.walk(tree)
                               if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                               and node.func.id in helper_names)
        modules[name] = {"declarations": declarations(tree), "layout_helpers": dict(helper_calls), **controls(tree)}
    tools = assigned(trees["app/core/agent_runtime.py"], "AGENT_TOOLS")
    spec = importlib.util.spec_from_file_location("iface_audit_presets", root / "app/core/incar_presets.py")
    presets = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(presets)
    fixtures = ([], ["Al"], ["Fe", "Ni", "O"])
    preset_values = {name: [presets.get_incar_preset(name, elements) for elements in fixtures]
                     for name in presets.PRESET_LABELS}
    tests = {path.relative_to(root).as_posix(): declarations(ast.parse(path.read_text(encoding="utf-8-sig")))
             for path in (root / "tests").glob("test_*.py")}
    return {"app_files": sorted(files), "modules": modules,
            "algorithm_hashes": {name: algorithm_fingerprint(name, trees["app/core/" + name]) for name in COMPUTATIONAL_MODULES},
            "agent_tools": {name: tool["risk"] for name, tool in tools.items()},
            "preset_values": preset_values, "tests": tests}


def verify(root):
    current = snapshot(root)
    failures, changed_callbacks, layout_adaptations = [], [], []
    missing_files = sorted(set(BASELINE["app_files"]) - set(current["app_files"]))
    if missing_files:
        failures.append({"missing_original_app_files": missing_files})
    for name, expected in BASELINE["modules"].items():
        actual = current["modules"].get(name)
        if actual is None:
            continue
        missing = sorted(set(expected["declarations"]) - set(actual["declarations"]))
        if missing:
            failures.append({"module": name, "missing_declarations": missing})
        for kind in ("events", "widgets"):
            lost = Counter(expected[kind]) - Counter(actual[kind])
            if lost:
                reviewed = REVIEWED_LAYOUT_ADAPTATIONS.get(name, {})
                if (kind == "widgets" and dict(lost) == reviewed.get("replaced")
                        and actual.get("layout_helpers") == reviewed.get("helpers")):
                    layout_adaptations.append({"module": name, **reviewed})
                else:
                    failures.append({"module": name, "missing_" + kind: dict(lost)})
        old_count, new_count = sum(expected["commands"].values()), sum(actual["commands"].values())
        if new_count < old_count:
            failures.append({"module": name, "lost_command_count": old_count - new_count})
        if expected["commands"] != actual["commands"]:
            changed_callbacks.append({"module": name, "original": old_count, "linux": new_count})
    for name, expected in BASELINE["tests"].items():
        missing = sorted(set(expected) - set(current["tests"].get(name, [])))
        if missing:
            failures.append({"test_module": name, "missing_original_tests": missing})
    for name, expected in BASELINE["algorithm_hashes"].items():
        expected = REVIEWED_GEOMETRY_CORRECTIONS.get(name, expected)
        if current["algorithm_hashes"].get(name) != expected:
            failures.append({"changed_computational_logic": name})
    for key in ("agent_tools", "preset_values"):
        if current[key] != BASELINE[key]:
            failures.append({"changed_original_contract": key})
    preflight = ast.parse((Path(root) / "app/core/task_preflight.py").read_text(encoding="utf-8-sig"))
    placeholder_sets = [{value.value for value in node.elts}
                        for node in ast.walk(preflight) if isinstance(node, ast.Tuple)
                        and all(isinstance(value, ast.Constant) and isinstance(value.value, str) for value in node.elts)]
    bilingual_tokens = {"请填写", "自动填写", "Enter a value", "Auto-fill", "TODO", "<", ">"}
    if not any(tokens == bilingual_tokens for tokens in placeholder_sets):
        failures.append({"missing_bilingual_placeholder_validation": sorted(bilingual_tokens)})
    return {"passed": not failures, "baseline_version": BASELINE["baseline_version"],
            "baseline_manifest_sha256": BASELINE["baseline_manifest_sha256"],
            "original_app_files": len(BASELINE["app_files"]), "linux_app_files": len(current["app_files"]),
            "original_declarations": sum(len(value["declarations"]) for value in BASELINE["modules"].values()),
            "original_test_declarations": sum(len(value) for value in BASELINE["tests"].values()),
            "original_presets": len(BASELINE["preset_values"]), "original_agent_tools": len(BASELINE["agent_tools"]),
            "failures": failures, "callback_implementation_changes_for_review": changed_callbacks,
            "reviewed_layout_adaptations": layout_adaptations,
            "reviewed_geometry_corrections": REVIEWED_GEOMETRY_CORRECTIONS,
            "accepted_localization_delta": "task_preflight: English placeholder synonyms are allowed only alongside all five original placeholder tokens.",
            "scope": "Static declarations, control counts, original test retention, computational ASTs, preset fixtures and tool risks. Run regression tests and desktop acceptance separately."}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--report", type=Path)
    arguments = parser.parse_args(argv)
    try:
        report = verify(arguments.root)
    except (OSError, SyntaxError, ValueError, KeyError) as error:
        report = {"passed": False, "error": str(error)}
    text = json.dumps(report, ensure_ascii=False, indent=2) + "\n"
    if arguments.report:
        arguments.report.parent.mkdir(parents=True, exist_ok=True)
        arguments.report.write_text(text, encoding="utf-8")
    print(text, end="")
    return 0 if report["passed"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
